<?php
/**
 * ChatHelp — apply-navy-icon (CH_NAVY_ICON) — lacivert CH ikonunu favicon
 *  olarak <head>'e ve sol menu ust bar'daki ".sb-logo" site basligina
 *  (Chat|Help metninin yanina, ikon+wordmark) ekler.
 *  [1] icon-16/32/64/180.png dosyalarini diske yazar (base64 gomulu, ayni
 *      PNG'ler kullanicinin onayladigi navy CH ikon).
 *  [2] <head>'e favicon + apple-touch-icon link'leri ekler (mevcut hic
 *      favicon YOK, dogrulandi — dump-header-logo/dump-header-logo3).
 *  [3] .sb-logo icine (onclick="NC()", TEK esleşme, dogrulandi)
 *      <img src="icon-64.png"> ekler, "Chat"+"Help" metinlerinden ONCE.
 * KULLANIM: pull2.php?key=...&files=apply-navy-icon.php
 */
header('Content-Type: text/plain; charset=UTF-8');
error_reporting(E_ERROR | E_PARSE);
echo "apply-navy-icon BASLADI OK (PHP ".PHP_VERSION.")\n\n";

$D = __DIR__;
$file = "$D/index.php";
$src = @file_get_contents($file);
if ($src===false) exit("index.php okunamadi\n");
if (strpos($src,'CH_NAVY_ICON')!==false) exit("Zaten ekli (CH_NAVY_ICON).\n");

$fail=[];
/* ── [1] ikon PNG dosyalarini yaz (base64) ── */
$png16 = base64_decode(<<<'B64'

B64
);
$w16 = @file_put_contents("$D/icon-16.png", $png16);
if ($w16===false || $w16<100) { echo "  ✗ [1] icon-16.png yazilamadi\n"; $fail[]='png16'; }
else echo "  ✓ [1] icon-16.png yazildi (" . $w16 . " bayt)\n";
$png32 = base64_decode(<<<'B64'

B64
);
$w32 = @file_put_contents("$D/icon-32.png", $png32);
if ($w32===false || $w32<100) { echo "  ✗ [1] icon-32.png yazilamadi\n"; $fail[]='png32'; }
else echo "  ✓ [1] icon-32.png yazildi (" . $w32 . " bayt)\n";
$png64 = base64_decode(<<<'B64'

B64
);
$w64 = @file_put_contents("$D/icon-64.png", $png64);
if ($w64===false || $w64<100) { echo "  ✗ [1] icon-64.png yazilamadi\n"; $fail[]='png64'; }
else echo "  ✓ [1] icon-64.png yazildi (" . $w64 . " bayt)\n";
$png180 = base64_decode(<<<'B64'

B64
);
$w180 = @file_put_contents("$D/icon-180.png", $png180);
if ($w180===false || $w180<100) { echo "  ✗ [1] icon-180.png yazilamadi\n"; $fail[]='png180'; }
else echo "  ✓ [1] icon-180.png yazildi (" . $w180 . " bayt)\n";

if ($fail) { echo "\nHATA: ikon dosyalari yazilamadi — index.php DEGISTIRILMEDI.\n"; exit; }

/* ── [2] <head>: favicon + apple-touch-icon ── */
$o1 = <<<'ANC'
<meta http-equiv="Expires" content="0">
<meta charset="UTF-8">
ANC;
$n1 = <<<'ANC'
<meta http-equiv="Expires" content="0">
<!--CH_NAVY_ICON-->
<link rel="icon" type="image/png" sizes="16x16" href="/chat/icon-16.png">
<link rel="icon" type="image/png" sizes="32x32" href="/chat/icon-32.png">
<link rel="icon" type="image/png" sizes="64x64" href="/chat/icon-64.png">
<link rel="apple-touch-icon" sizes="180x180" href="/chat/icon-180.png">
<meta charset="UTF-8">
ANC;
$c1 = substr_count($src,$o1);
if ($c1!==1) { echo "  ✗ [2] <head> favicon anchor ($c1)\n"; $fail[]='2'; }
else { $src = str_replace($o1,$n1,$src); echo "  ✓ [2] favicon + apple-touch-icon <head>'e eklendi\n"; }

/* ── [3] .sb-logo: ikon + wordmark ── */
$o2 = <<<'ANC'
<div class="sb-logo" onclick="NC()"><span style="color:#fff;font-weight:800">Chat</span><span style="background:linear-gradient(135deg,#d4a84a,#f0c860);-webkit-background-clip:text;-webkit-text-fill-color:transparent;font-weight:800">Help</span></div>
ANC;
$n2 = <<<'ANC'
<div class="sb-logo" onclick="NC()"><img src="/chat/icon-64.png" alt="ChatHelp" style="width:26px;height:26px;border-radius:8px;flex:0 0 auto"><span style="color:#fff;font-weight:800">Chat</span><span style="background:linear-gradient(135deg,#d4a84a,#f0c860);-webkit-background-clip:text;-webkit-text-fill-color:transparent;font-weight:800">Help</span></div>
ANC;
$c2 = substr_count($src,$o2);
if ($c2!==1) { echo "  ✗ [3] .sb-logo anchor ($c2)\n"; $fail[]='3'; }
else { $src = str_replace($o2,$n2,$src); echo "  ✓ [3] Site basligina (sb-logo) navy CH ikonu eklendi\n"; }

if ($fail) { echo "\nHATA: eslesmeyen adimlar: ".implode(', ',$fail)." — index.php DEGISTIRILMEDI (ikon PNG'leri diskte kaldi, zararsiz).\n"; exit; }

$tmp = tempnam(sys_get_temp_dir(),'ni').'.php';
file_put_contents($tmp,$src);
$lo=[];$rc=0; exec('php -l '.escapeshellarg($tmp).' 2>&1',$lo,$rc); @unlink($tmp);
if ($rc!==0) { echo "\nLINT HATASI — index.php DEGISTIRILMEDI:\n  ".implode("\n  ",$lo)."\n"; exit; }
@file_put_contents($file.'.bak-navyicon-'.date('Ymd-His'), (string)@file_get_contents($file));
$w=@file_put_contents($file,$src);
if ($w===false || $w<strlen($src)) { echo "\n✗ YAZMA HATASI.\n"; exit; }
$chk=(string)@file_get_contents($file);
if (strpos($chk,'CH_NAVY_ICON')===false || strpos($chk,'icon-64.png')===false) { echo "\n✗ DOGRULAMA BASARISIZ.\n"; exit; }
echo "\n  ✓ DOGRULAMA: CH_NAVY_ICON diskte (".strlen($chk)." bayt)\n";
echo "\n✓ Navy CH ikonu: tarayici sekmesinde (favicon), telefon ana ekranda (apple-touch-icon)\n";
echo "   ve sol menu ust basliginda (sb-logo, Chat|Help yazisinin yaninda) aktif.\n";
